// Separa cada adjunto PDF/XML del correo en un item propio.
// Si el correo trae XML de factura electrónica, se usa el XML y se ignora el PDF.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const bin = it.binary || {};
  const meta = {
    message_id: it.json.id || '',
    remitente: it.json.from?.value?.[0]?.address || '',
    asunto: it.json.subject || '',
    fecha_recepcion: new Date(it.json.date || Date.now()).toISOString(),
  };
  const adjuntos = [];
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    const nombre = (b.fileName || key).toLowerCase();
    const mime = (b.mimeType || '').toLowerCase();
    const esXml = nombre.endsWith('.xml') || mime.includes('xml');
    const esPdf = nombre.endsWith('.pdf') || mime.includes('pdf');
    if (!esXml && !esPdf) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    let contenido;
    if (esXml) {
      const cabecera = buf.subarray(0, 120).toString('ascii');
      contenido = buf.toString(/ISO-8859-1/i.test(cabecera) ? 'latin1' : 'utf8');
    } else {
      contenido = buf.toString('base64');
    }
    adjuntos.push({ tipo: esXml ? 'xml' : 'pdf', archivo: b.fileName || key, contenido });
  }
  const usar = adjuntos.some(a => a.tipo === 'xml') ? adjuntos.filter(a => a.tipo === 'xml') : adjuntos;
  for (const a of usar) out.push({ json: { ...meta, ...a }, pairedItem: { item: i } });
}
return out;

// Lee el XML de factura electrónica del SII sin usar IA.
const tag = (x, t) => {
  const m = (x || '').match(new RegExp('<' + t + '>([\\s\\S]*?)</' + t + '>'));
  return m ? m[1].trim() : null;
};
const num = v => (v == null || v === '') ? 0 : Number(v);
const TIPOS = { '33': 'factura_afecta', '34': 'factura_exenta', '61': 'nota_credito' };
const fmtRut = r => {
  if (!r) return null;
  const [cuerpo, dv] = r.replace(/\./g, '').split('-');
  return cuerpo.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '-' + (dv || '').toUpperCase();
};
return $input.all().map((it, i) => {
  const x = it.json.contenido;
  const doc = (x.match(/<Documento[\s\S]*?<\/Documento>/) || [x])[0];
  const items = [...doc.matchAll(/<Detalle>([\s\S]*?)<\/Detalle>/g)]
    .map(m => ({ descripcion: tag(m[1], 'NmbItem'), monto: num(tag(m[1], 'MontoItem')) }));
  const refs = [...doc.matchAll(/<Referencia>([\s\S]*?)<\/Referencia>/g)].map(m => m[1]);
  const oc = refs.find(r => tag(r, 'TpoDocRef') === '801');
  const { contenido, tipo, ...meta } = it.json;
  return {
    json: {
      ...meta,
      origen: 'XML',
      factura: {
        tipo_documento: TIPOS[tag(doc, 'TipoDTE')] || ('dte_' + tag(doc, 'TipoDTE')),
        rut_emisor: fmtRut(tag(doc, 'RUTEmisor')),
        razon_social_emisor: tag(doc, 'RznSoc'),
        folio: tag(doc, 'Folio'),
        fecha_emision: tag(doc, 'FchEmis'),
        fecha_vencimiento: tag(doc, 'FchVenc'),
        condicion_pago: tag(doc, 'TermPagoGlosa') || tag(doc, 'FmaPago'),
        monto_neto: num(tag(doc, 'MntNeto')),
        monto_exento: num(tag(doc, 'MntExe')),
        iva: num(tag(doc, 'IVA')),
        monto_total: num(tag(doc, 'MntTotal')),
        glosa: items.map(x => x.descripcion).filter(Boolean).join('; ').slice(0, 200),
        numero_oc: oc ? tag(oc, 'FolioRef') : null,
        items,
      },
    },
    pairedItem: { item: i },
  };
});

// Convierte el PDF a binario para que Claude lo lea completo (sirve para PDF digital y escaneado).
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const { contenido, tipo, ...meta } = items[i].json;
  const data = await this.helpers.prepareBinaryData(
    Buffer.from(contenido, 'base64'), meta.archivo || 'factura.pdf', 'application/pdf');
  out.push({ json: { meta }, binary: { data }, pairedItem: { item: i } });
}
return out;

// Toma el JSON devuelto por Claude y lo une con los datos del correo.
const textoDe = j => {
  if (typeof j === 'string') return j;
  if (Array.isArray(j?.content)) return j.content.filter(c => c.type === 'text').map(c => c.text).join('');
  if (typeof j?.content === 'string') return j.content;
  return j?.text || j?.output || j?.response || j?.merged_response || '';
};
const texto = textoDe($json);
let factura;
try {
  factura = JSON.parse((texto.match(/\{[\s\S]*\}/) || ['{}'])[0]);
} catch (e) {
  factura = { error_parseo: texto.slice(0, 300) };
}
if (!texto) factura = { error_parseo: 'Respuesta vacía: ' + JSON.stringify($json).slice(0, 250) };
const meta = $('Preparar PDF').item.json.meta;
return { json: { ...meta, origen: 'PDF', factura } };

// 1) Valida montos y RUT. 2) Clasifica con el catálogo histórico de contabilidad.
const catalogo = $('Leer catálogo').all().map(i => i.json).filter(r => r.proveedor);
const norm = s => ' ' + (s || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^A-Z0-9]+/g, ' ') + ' ';
const limpiar = s => norm(s)
  .replace(/ (SOCIEDAD ANONIMA|SOCIEDAD|SPA|S P A|S A|LTDA|LIMITADA|EIRL|E I R L|CIA|Y CIA|CHILE) /g, ' ')
  .replace(/ (SOCIEDAD ANONIMA|SOCIEDAD|SPA|S P A|S A|LTDA|LIMITADA|EIRL|E I R L|CIA|Y CIA|CHILE) /g, ' ')
  .replace(/\s+/g, ' ').trim();
const porProveedor = {};
for (const r of catalogo) (porProveedor[limpiar(r.proveedor)] ||= []).push(r);
const opciones = [...new Map(catalogo.map(r => [r.cuenta + '|' + r.concepto,
  { cuenta: String(r.cuenta), nombre_cuenta: r.nombre_cuenta, concepto: r.concepto }])).values()];

const rutValido = r => {
  const m = (r || '').replace(/\./g, '').toUpperCase().match(/^(\d{6,9})-([\dK])$/);
  if (!m) return false;
  let s = 0, mul = 2;
  for (const d of m[1].split('').reverse()) { s += Number(d) * mul; mul = mul === 7 ? 2 : mul + 1; }
  const dv = 11 - (s % 11);
  return (dv === 11 ? '0' : dv === 10 ? 'K' : String(dv)) === m[2];
};

return $input.all().map((it, i) => {
  const f = it.json.factura || {};
  const motivos = [];
  if (f.error_parseo) motivos.push('La IA no devolvió un JSON válido');
  for (const c of ['rut_emisor', 'folio', 'fecha_emision', 'monto_total'])
    if (f[c] == null || f[c] === '' || f[c] === 0) motivos.push('Falta ' + c);
  if (f.rut_emisor && !rutValido(f.rut_emisor)) motivos.push('RUT emisor con dígito verificador inválido');
  const neto = Number(f.monto_neto) || 0, exento = Number(f.monto_exento) || 0;
  const iva = Number(f.iva) || 0, total = Number(f.monto_total) || 0;
  if (f.tipo_documento !== 'factura_exenta' && neto > 0 && Math.abs(iva - Math.round(neto * 0.19)) > 1)
    motivos.push('IVA no es 19% del neto');
  if (Math.abs(neto + exento + iva - total) > 1) motivos.push('Neto + exento + IVA no suma el total');
  const items = Array.isArray(f.items) ? f.items : [];
  if (items.length && Math.abs(items.reduce((s, x) => s + (Number(x.monto) || 0), 0) - (neto + exento)) > 1)
    motivos.push('La suma de los ítems no cuadra con neto + exento');

  // Clasificación por catálogo
  const clave = limpiar(f.razon_social_emisor);
  let candidatos = porProveedor[clave] || [];
  if (!candidatos.length && clave.length >= 5) {
    const k = Object.keys(porProveedor).find(p => p.length >= 5 && (p.includes(clave) || clave.includes(p)));
    if (k) candidatos = porProveedor[k];
  }
  let clasif = null;
  if (candidatos.length === 1) {
    const r = candidatos[0];
    clasif = { cuenta: String(r.cuenta), nombre_cuenta: r.nombre_cuenta, concepto: r.concepto, ceco: r.ceco, origen: 'CATALOGO' };
  }
  return {
    json: { ...it.json, validacion: { motivos }, clasif, necesita_ia: !clasif, candidatos, opciones },
    pairedItem: { item: i },
  };
});

// Arma la consulta de clasificación para proveedores nuevos o con más de una cuenta posible.
return $input.all().map((it, i) => {
  const f = it.json.factura || {};
  const { opciones, candidatos, ...base } = it.json;
  const prompt = [
    'Clasifica contablemente una factura recibida por la clínica SGFertility.',
    'Proveedor: ' + (f.razon_social_emisor || 'desconocido'),
    'Ítems: ' + JSON.stringify((f.items || []).map(x => x.descripcion)),
    'Glosa: ' + (f.glosa || ''),
    'Clasificaciones históricas de este proveedor (pueden estar vacías): ' +
      JSON.stringify(candidatos.map(c => ({ cuenta: String(c.cuenta), nombre_cuenta: c.nombre_cuenta, concepto: c.concepto, ceco: c.ceco, pct: c.pct_del_proveedor }))),
    'Opciones válidas de cuenta y concepto: ' + JSON.stringify(opciones),
    'Elige UNA combinación que exista en las opciones válidas; si los ítems calzan con una clasificación histórica, prefiérela.',
    'Si no hay información de CECO usa "ADMINISTRACION".',
    'Responde SOLO un objeto JSON, sin texto adicional ni bloques de código, con: cuenta, nombre_cuenta, concepto, ceco, confianza (número entre 0 y 1) y justificacion (una frase).',
  ].join('\n');
  return { json: { base, prompt }, pairedItem: { item: i } };
});

// Aplica la clasificación sugerida por Claude.
const textoDe = j => {
  if (typeof j === 'string') return j;
  if (Array.isArray(j?.content)) return j.content.filter(c => c.type === 'text').map(c => c.text).join('');
  if (typeof j?.content === 'string') return j.content;
  return j?.text || j?.output || j?.response || j?.merged_response || '';
};
const texto = textoDe($json);
let r = {};
try { r = JSON.parse((texto.match(/\{[\s\S]*\}/) || ['{}'])[0]); } catch (e) {}
const base = $('Preparar clasificación').item.json.base;
const motivos = [...base.validacion.motivos];
if (!r.cuenta) motivos.push('La IA no pudo clasificar la factura');
else if (Number(r.confianza) < 0.6) motivos.push('Clasificación IA con baja confianza');
return {
  json: {
    ...base,
    validacion: { motivos },
    clasif: {
      cuenta: r.cuenta ? String(r.cuenta) : '',
      nombre_cuenta: r.nombre_cuenta || '',
      concepto: r.concepto || '',
      ceco: r.ceco || 'ADMINISTRACION',
      origen: 'LLM',
    },
  },
};

// Arma la fila de cabecera (facturas) y las filas de detalle (facturas_detalle).
const f = $json.factura || {};
const c = $json.clasif || {};
const motivos = $json.validacion?.motivos || [];
const signo = f.tipo_documento === 'nota_credito' ? -1 : 1;
const n = v => signo * (Number(v) || 0);
const fila = {
  id: (f.rut_emisor || 'SIN-RUT') + '_' + (f.folio || 'SIN-FOLIO'),
  fecha_recepcion: $json.fecha_recepcion,
  tipo_documento: f.tipo_documento || '',
  rut_emisor: f.rut_emisor || '',
  razon_social_emisor: f.razon_social_emisor || '',
  folio: f.folio != null ? String(f.folio) : '',
  fecha_emision: f.fecha_emision || '',
  fecha_vencimiento: f.fecha_vencimiento || '',
  condicion_pago: f.condicion_pago || '',
  monto_neto: n(f.monto_neto),
  monto_exento: n(f.monto_exento),
  iva: n(f.iva),
  monto_total: n(f.monto_total),
  glosa: f.glosa || '',
  numero_oc: f.numero_oc != null ? String(f.numero_oc) : '',
  servicio: '',
  cuenta: c.cuenta || '',
  concepto: c.concepto || '',
  ceco: c.ceco || '',
  clasificacion_origen: c.origen || '',
  origen: $json.origen,
  estado_validacion: motivos.length ? 'REVISAR' : 'OK',
  motivo_revision: motivos.join('; '),
  archivo: $json.archivo || '',
};
const lineas = (Array.isArray(f.items) && f.items.length)
  ? f.items
  : [{ descripcion: f.glosa || '', monto: (Number(f.monto_neto) || 0) + (Number(f.monto_exento) || 0) }];
const detalle = lineas.map(x => ({
  folio: fila.folio,
  rut_emisor: fila.rut_emisor,
  proveedor: fila.razon_social_emisor,
  fecha: fila.fecha_emision,
  descripcion: x.descripcion || '',
  monto: n(x.monto),
  cuenta: fila.cuenta,
  nombre_cuenta: c.nombre_cuenta || '',
  concepto: fila.concepto,
  ceco: fila.ceco,
}));
return { json: { fila, detalle } };

return $input.all().map((it, i) => ({
  json: {
    timestamp: new Date().toISOString(),
    workflow: 'SGF - Ingreso facturas',
    estado: it.json.estado_validacion,
    detalle: `Factura ${it.json.folio} de ${it.json.razon_social_emisor} (${it.json.origen})` +
      (it.json.motivo_revision ? ' – ' + it.json.motivo_revision : ''),
  },
  pairedItem: { item: i },
}));

return $input.all().map((it, i) => ({
  json: {
    timestamp: new Date().toISOString(),
    workflow: 'SGF - Ingreso facturas',
    estado: 'ERROR',
    detalle: 'Falló la llamada a la IA: ' + JSON.stringify(it.json.error || it.json).slice(0, 400),
  },
  pairedItem: { item: i },
}));
